import pyomo.environ as pyo

DATA = {
    "foods": ["Food_1", "Food_2", "Food_3", "Food_4", "Food_5", "Food_6"],
    "cost": {
        "Food_1": 4, "Food_2": 2, "Food_3": 6,
        "Food_4": 2, "Food_5": 6, "Food_6": 8,
    },
    "protein": {
        "Food_1": 17, "Food_2": 4, "Food_3": 7,
        "Food_4": 14, "Food_5": 13, "Food_6": 1,
    },
    "carbs": {
        "Food_1": 8, "Food_2": 24, "Food_3": 27,
        "Food_4": 16, "Food_5": 1, "Food_6": 13,
    },
    "calories": {
        "Food_1": 237, "Food_2": 213, "Food_3": 133,
        "Food_4": 118, "Food_5": 136, "Food_6": 225,
    },
    "req_protein": 76,
    "req_carbs": 173,
    "req_calories": 1751,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Set of foods
    model.F = pyo.Set(initialize=d["foods"])

    # Variable: servings of each food (nonnegative, no explicit upper bound)
    model.x = pyo.Var(model.F, within=pyo.NonNegativeReals, bounds=(0, None))

    # Objective: minimize total cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.F)
    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Protein requirement: at least req_protein grams
    def protein_rule(m):
        return sum(d["protein"][i] * m.x[i] for i in m.F) >= d["req_protein"]
    model.protein_con = pyo.Constraint(rule=protein_rule)

    # Carbohydrate requirement: at least req_carbs grams
    def carb_rule(m):
        return sum(d["carbs"][i] * m.x[i] for i in m.F) >= d["req_carbs"]
    model.carb_con = pyo.Constraint(rule=carb_rule)

    # Calorie requirement: at least req_calories
    def cal_rule(m):
        return sum(d["calories"][i] * m.x[i] for i in m.F) >= d["req_calories"]
    model.calorie_con = pyo.Constraint(rule=cal_rule)

    return model


